package com.maikal.courses;
import android.content.Context;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.graphics.drawable.Drawable;import java.io.*;
final class Certificate {
 static byte[] create(Context context,String name,String course,String date)throws IOException{PdfDocument doc=new PdfDocument();PdfDocument.Page page=doc.startPage(new PdfDocument.PageInfo.Builder(842,595,1).create());Canvas c=page.getCanvas();Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);c.drawColor(Color.rgb(255,250,241));p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3);p.setColor(Color.rgb(210,169,105));c.drawRoundRect(25,25,817,570,20,20,p);p.setStrokeWidth(1);c.drawRoundRect(34,34,808,561,15,15,p);p.setStyle(Paint.Style.FILL);Drawable fox=context.getDrawable(R.drawable.ic_logo);fox.setBounds(378,49,464,135);fox.draw(c);text(c,p,"MAIKAL COURSES",421,159,14,Color.rgb(158,111,71),true);text(c,p,"Certificate of completion",421,209,37,Color.rgb(64,49,76),true);text(c,p,"This celebrates",421,248,15,Color.rgb(128,106,128),false);fit(c,p,name,421,302,44,690,Color.rgb(165,93,69));text(c,p,"for completing the course",421,339,15,Color.rgb(128,106,128),false);fit(c,p,course,421,382,31,700,Color.rgb(64,49,76));text(c,p,"You completed "+course+" from Maikal Courses.",421,422,14,Color.rgb(100,81,108),false);text(c,p,"Thank you and all the best.",421,451,17,Color.rgb(165,93,69),true);text(c,p,"Completed "+date+"  |  Independent, self-paced learning",421,511,11,Color.rgb(136,112,128),false);text(c,p,"This is a course completion record, not an accredited qualification.",421,531,9,Color.rgb(153,132,144),false);doc.finishPage(page);ByteArrayOutputStream out=new ByteArrayOutputStream();doc.writeTo(out);doc.close();return out.toByteArray();}
 static void text(Canvas c,Paint p,String text,float x,float y,float size,int color,boolean bold){p.setTextSize(size);p.setColor(color);p.setTypeface(Typeface.create("sans-serif",bold?Typeface.BOLD:Typeface.NORMAL));p.setTextAlign(Paint.Align.CENTER);c.drawText(text,x,y,p);}
 static void fit(Canvas c,Paint p,String text,float x,float y,float size,float width,int color){p.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));p.setTextSize(size);float measured=p.measureText(text);text(c,p,text,x,y,measured>width?size*width/measured:size,color,true);}
}
